export function clamp(n) { return Math.min(100,Math.max(0,Math.round(n))); }
export function readiness(controls = CONTROLS) {
  const counts = {measured:0,planned:0,missing:0};
  for (const c of controls) {
    if (!Object.hasOwn(counts,c.state)) throw new Error('Invalid assessment state: '+c.state);
    counts[c.state]++;
  }
  return {total:controls.length,counts,eligible:false,authorization:'NOT AUTHORIZED',basis:'Demonstration self-assessment; external authorization never inferred from tests.'};
}
export function newExercise(id='communication') {
  const drill=DRILLS.find(x=>x.id===id);
  if(!drill) throw new RangeError('Unknown defensive exercise');
  return {id:drill.id,day:0,running:false,metrics:{comms:97,supply:95,medical:94,civilian:96,infrastructure:95},events:[{day:0,type:'INIT',message:'Local synthetic exercise created'}],samples:[]};
}
export function inject(ex) {
  if(ex.day>100) return ex;
  const drill=DRILLS.find(x=>x.id===ex.id);
  const metrics={...ex.metrics};
  for(const k of Object.keys(metrics)) metrics[k]=clamp(metrics[k]-drill.impact[k]);
  return {...ex,metrics,events:[...ex.events,{day:ex.day,type:'SIMULATED_DISRUPTION',message:drill.label}]};
}
export function advance(ex,steps=1) {
  if(!Number.isInteger(steps)||steps<1||steps>100) throw new RangeError('Invalid step count');
  let next={...ex,metrics:{...ex.metrics},events:[...ex.events],samples:[...ex.samples]};
  for(let n=0;n<steps && next.day<100;n++) {
    next.day++;
    for(const [i,k] of Object.keys(next.metrics).entries()) {
      const baseline={comms:97,supply:95,medical:94,civilian:96,infrastructure:95}[k];
      const gap=baseline-next.metrics[k];
      const recovery=gap>0 ? Math.max(1,Math.ceil(gap/14)) : 0;
      const variation=((next.day+i*3)%11===0)?-1:0;
      next.metrics[k]=clamp(Math.min(baseline,next.metrics[k]+recovery+variation));
    }
    next.samples.push({day:next.day,...next.metrics});
  }
  return next;
}
export function ontology(ex) {
  const drill=DRILLS.find(x=>x.id===ex.id);
  const nodes=[
    {id:'exercise:'+ex.id,type:'synthetic_exercise',label:drill.label,provenance:'local_simulator'},
    ...CHANNELS.map(c=>({id:'channel:'+c.id,type:'synthetic_channel',label:c.label,provenance:'local_simulator'})),
    ...CONTROLS.map(c=>({id:'control:'+c.id,type:'self_assessment',label:c.name,provenance:'public_source_review',state:c.state}))
  ];
  const edges=[
    ...CHANNELS.map(c=>({from:'exercise:'+ex.id,to:'channel:'+c.id,relation:'SIMULATES'})),
    ...CONTROLS.map(c=>({from:'control:'+c.id,to:'exercise:'+ex.id,relation:'GOVERNS_REVIEW_OF'}))
  ];
  return {schema:'xunia.readiness.ontology.v1',nodes,edges,classification:'PUBLIC DEMO ONLY'};
}
export function report(ex) {
  return {schema:'xunia.readyroom.aar.v1',generatedAt:new Date().toISOString(),dataClass:'SYNTHETIC PUBLIC EXERCISE',authorization:AUTHORIZATION,readiness:readiness(),exercise:{...ex},ontology:ontology(ex),digestNote:'SHA-256 is a local corruption hint, NOT an authenticated signature or trusted timestamp'};
}
